// Blog posts batch 5 (2026-10-16): lamb chops, cutlets, skewers and everyday lamb. Rules in posts-blog.js.
import { BLOG_KEYWORDS } from './posts-blog-keywords.js'

const meta = (slug) => ({ slug, kw: BLOG_KEYWORDS[slug].focus, keywords: BLOG_KEYWORDS[slug].keywords, date: '2026-10-16', updated: '2026-10-16' })

export const BLOG_POSTS_5 = [
  {
    ...meta('lamb-souvlaki'),
    title: 'Lamb Souvlaki: A Greek Recipe for Skewers and Wraps',
    seoTitle: 'Lamb Souvlaki Recipe: Easy Greek Skewers',
    excerpt: `A Greek lamb souvlaki recipe: lemon, garlic and oregano marinade, the best halal lamb cuts, grilling tips, homemade tzatziki and the perfect wrap.`,
    body: [
      ['p', `Lamb souvlaki is Greek street food at its best: chunks of lamb marinated in lemon, garlic, olive oil and oregano, threaded onto skewers and grilled over high heat until charred at the edges and juicy in the middle. Served on a plate with Greek salad and lemon potatoes, or wrapped in warm pita with tzatziki, tomato and onion, it is one of the most popular takeaway meals in Australia, and one of the easiest to make at home. This guide covers a classic Greek lamb souvlaki recipe, the best cuts, grilling technique and all the trimmings.`],
      ['h2', `What is souvlaki?`],
      ['p', `Souvlaki means "little skewer" in Greek. Traditionally it describes small pieces of meat grilled on skewers, while gyros is meat cooked on a vertical rotisserie and shaved off. In Melbourne and Sydney, the word souvlaki is often used for both, especially when served in a wrap. Several meats are used across Greece, but lamb souvlaki is a favourite in Australian Greek restaurants and the natural choice for a halal kitchen.`],
      ['h2', `Choosing the lamb`],
      ['p', `Souvlaki is grilled quickly, so it needs a cut that is tender but has enough fat to stay juicy. Good choices include:`],
      ['ul', [
        `[Lamb leg, butterflied](/product/lamb-leg-butterflied/): our first pick. Boneless, easy to cube and nicely balanced between lean and fat.`,
        `[Lamb shoulder, boned and rolled](/product/lamb-shoulder-boned-and-rolled/): richer and juicier, with more fat; ideal if you like a softer texture.`,
        `[Lamb rump](/product/lamb-rump/): tender and flavourful, great for a premium souvlaki.`,
        `[Lamb backstrap](/product/lamb-backstrap/): very tender and lean; cook it pink and do not overdo it.`,
        `[Diced lamb](/product/diced-lamb-boneless/): ready-cut for convenience.`,
      ]],
      ['p', `Cut the lamb into 3 cm cubes and trim off any thick sinew. Allow about 180 to 200 g of boneless lamb per person.`],
      ['h2', `Greek lamb souvlaki recipe`],
      ['p', `This Greek lamb souvlaki recipe serves four.`],
      ['h3', `Marinade`],
      ['ul', [
        `800 g boneless lamb leg or shoulder, cut into 3 cm cubes`,
        `1/3 cup extra virgin olive oil`,
        `Juice and zest of 1 lemon`,
        `4 cloves garlic, crushed`,
        `2 teaspoons dried Greek oregano`,
        `1 teaspoon each salt, cracked black pepper and sweet paprika`,
        `1 tablespoon white vinegar or extra lemon juice`,
      ]],
      ['p', `Mix the marinade ingredients and toss through the lamb. Cover and refrigerate for at least 2 hours and up to 12 hours. Lemon tenderises the surface, so avoid marinating for more than a day.`],
      ['h3', `Grilling the skewers`],
      ['p', `Soak bamboo skewers in water for 30 minutes, or use metal skewers. Thread the lamb onto the skewers, leaving a small gap between pieces. Heat a barbecue, chargrill or grill pan until very hot and oil the bars. Cook the skewers for 8 to 10 minutes, turning every 2 minutes, until charred on the outside and still slightly pink inside. Rest for 3 to 5 minutes, then squeeze over fresh lemon and sprinkle with a little more oregano and flaky salt.`],
      ['h2', `Roasting option: lamb souvlaki in the oven`],
      ['p', `No barbecue? Spread the marinated lamb in a single layer in a large roasting pan for lamb, or on a lined tray, and roast at 230°C for 12 to 15 minutes, turning once, then finish under a hot grill for 2 to 3 minutes to char the edges. A heavy, shallow roasting pan gives the best colour; deep dishes trap steam and the meat stews rather than browns. You can also roast thick slices of onion and capsicum in the same pan for a complete meal.`],
      ['h2', `Homemade tzatziki`],
      ['p', `Grate a Lebanese cucumber, squeeze out as much liquid as possible, and mix with 1 cup thick Greek yoghurt, 1 crushed garlic clove, 1 tablespoon olive oil, a squeeze of lemon, chopped dill or mint and salt. Rest for 30 minutes so the flavours mingle. It keeps for three days in the fridge.`],
      ['h2', `Building the perfect souvlaki wrap`],
      ['p', `Warm a thick Greek-style pita on the grill until soft and lightly charred. Spread with tzatziki, add the lamb, sliced tomato, thinly sliced red onion, a few chips if you like (a classic Melbourne touch), and a sprinkle of paprika and parsley. Wrap tightly in baking paper and foil, twisting the bottom so it holds together.`],
      ['h3', `Plate-style souvlaki`],
      ['p', `For a sit-down meal, serve the skewers with lemon-roasted potatoes, a Greek salad of tomato, cucumber, red onion, olives, capsicum and feta, a bowl of tzatziki and warm pita. It is a generous, colourful spread that is perfect for entertaining.`],
      ['h2', `Lamb souvlaki tips`],
      ['ul', [
        `Use Greek dried oregano if you can find it; it is more aromatic than most.`,
        `Cut the lamb evenly so every piece cooks at the same rate.`,
        `Get the grill very hot for a good char without overcooking the middle.`,
        `Do not crowd the skewers on the grill.`,
        `Rest the meat briefly before serving to keep it juicy.`,
      ]],
      ['h2', `Lamb souvlaki questions`],
      ['h3', `Which part of the lamb is best for souvlaki?`],
      ['p', `Boneless leg is the most popular because it is tender, easy to cube and not too fatty. Shoulder gives a juicier, richer result. Backstrap and rump are premium options.`],
      ['h3', `Can I make souvlaki ahead?`],
      ['p', `Yes. Marinate and thread the skewers the night before and keep them covered in the fridge. Grill just before serving.`],
      ['h3', `How do I make gyros-style lamb at home?`],
      ['p', `Marinate thin slices of lamb shoulder in the same mixture, stack them tightly in a loaf tin, roast at 180°C for about 1 hour, then slice thinly and crisp the slices in a hot pan.`],
      ['h3', `Can I use lamb mince?`],
      ['p', `Lamb mince is better suited to koftas and keftedes than souvlaki, but it makes an excellent Greek-style wrap filling. See our [lamb mince recipes](/blog/lamb-mince-recipes/) and [lamb kofta wraps](/blog/lamb-kofta-wraps/).`],
      ['p', `Leftover souvlaki lamb keeps for two days in the fridge. Reheat it quickly in a hot pan so the edges crisp again, then pile it into fresh pita with tzatziki and salad for an easy lunch.`],
      ['p', `For a party, set out a souvlaki bar with warm pita, bowls of tzatziki, sliced tomato, onion, lettuce, chips and lemon wedges, and let guests build their own.`],
      ['h2', `Lamb for sale: delivered Australia-wide`],
      ['p', `Looking for quality lamb for sale? Our [halal lamb range](/shop/lamb/) includes butterflied leg, shoulder, rump, backstrap and diced lamb, all cut in Greenacre, Sydney and certified halal by Halal Control Australia. We deliver chilled lamb Australia-wide, with free delivery on orders over $500. For a big family celebration, see our [whole lamb](/whole-lamb-aqeeqah-qurbani/) options, and for more grilling ideas read our [lamb skewers](/blog/lamb-skewers/) guide.`],
    ],
  },
  {
    ...meta('lamb-mince-recipes'),
    title: 'Lamb Mince Recipes: Eight Easy Meals for Every Night',
    seoTitle: 'Lamb Mince Recipes: 8 Easy Weeknight Meals',
    excerpt: `Eight lamb mince recipes and meal ideas: koftas, shepherd's pie, kibbeh bake, keema, lamb burgers, moussaka, stuffed vegetables and lamb flatbread.`,
    body: [
      ['p', `Lamb mince is one of the most flavourful and versatile ingredients you can keep in the fridge. It is richer and more aromatic than beef mince, it loves warm spices and fresh herbs, and it cooks quickly enough for a weeknight dinner. From Middle Eastern koftas to a classic shepherd's pie, it suits cuisines from all over the world. This collection of lamb mince recipes gives you eight reliable meals, plenty of lamb mince meal ideas and tips for cooking with it.`],
      ['h2', `Cooking with lamb mince: the basics`],
      ['p', `Lamb mince usually contains a little more fat than beef mince, which gives it great flavour and keeps dishes juicy. Brown it well over medium-high heat and, for saucy dishes, spoon off excess fat before adding other ingredients. Lamb pairs beautifully with cumin, coriander, cinnamon, allspice, paprika, mint, parsley, oregano, garlic, lemon and pomegranate. Our [lamb mince](/product/ground-lamb-meat-mince/) is ready to use for every recipe below, and our [lamb kofta](/product/lamb-kofta/) is pre-seasoned and ready to grill.`],
      ['h2', `1. Lamb koftas`],
      ['p', `This lamb mince recipe is a Middle Eastern classic. Mix 500 g lamb mince with a grated onion (squeezed dry), 2 crushed garlic cloves, a handful each of chopped parsley and mint, 1 teaspoon each of cumin, coriander and paprika, 1/2 teaspoon each of cinnamon and allspice, and salt. Shape into sausages around skewers and grill for 8 to 10 minutes, turning. Serve with flatbread, tabbouleh, hummus and garlic sauce. See our [lamb kofta wraps](/blog/lamb-kofta-wraps/) for more.`],
      ['h2', `2. Shepherd's pie`],
      ['p', `Brown 750 g lamb mince, remove, then soften a diced onion, carrot and celery stick. Add garlic, 2 tablespoons tomato paste, a tablespoon of flour, 2 cups beef or lamb stock, a splash of Worcestershire-style sauce (check it is alcohol-free) and thyme. Return the lamb and simmer for 25 minutes. Spoon into a dish, top with creamy mashed potato, rough up the surface with a fork and bake at 200°C for 25 minutes until golden. True shepherd's pie is always made with lamb.`],
      ['h2', `3. Lamb keema`],
      ['p', `Fry a diced onion until golden, add ginger, garlic and green chilli, then 2 teaspoons garam masala, 1 teaspoon each cumin and coriander and 1/2 teaspoon turmeric. Add 500 g lamb mince and brown well, then a chopped tomato and half a cup of water. Simmer for 15 minutes, add a cup of peas for 5 minutes more, and finish with coriander and lemon. Serve with rice or paratha.`],
      ['h2', `4. Greek-style moussaka`],
      ['p', `Layer slices of fried or roasted eggplant with a lamb mince sauce flavoured with cinnamon, allspice, oregano and tomato, and top with a thick béchamel enriched with egg yolk and parmesan. Bake at 180°C for 45 minutes and rest for 20 minutes before slicing. It is a project dish, but it can be made a day ahead and reheated.`],
      ['h2', `5. Lamb burgers`],
      ['p', `Mix 600 g lamb mince with crumbled feta, chopped mint, a crushed garlic clove, a teaspoon of cumin, salt and pepper. Shape into four patties and grill for 4 to 5 minutes a side until cooked through. Serve in toasted buns with tzatziki, rocket, tomato and red onion. Our [beef meat patties recipe](/blog/beef-meat-patties-recipe/) has more burger-shaping tips.`],
      ['h2', `6. Kibbeh-style baked lamb`],
      ['p', `For an easy version of the Levantine favourite, mix fine bulgur (soaked and squeezed) with half of 600 g lamb mince, a grated onion, cumin, allspice and salt. Press half into an oiled tray, top with the remaining mince fried with onion, pine nuts and cinnamon, then cover with the rest of the bulgur mixture. Score into diamonds, drizzle with olive oil and bake at 200°C for 35 to 40 minutes. Serve with yoghurt and salad.`],
      ['h2', `7. Stuffed vegetables`],
      ['p', `Hollow out capsicums, zucchini, tomatoes or eggplants. Mix lamb mince with cooked rice, chopped herbs, tomato paste, allspice and cinnamon, stuff the vegetables, and bake in a tomato sauce at 180°C for 50 to 60 minutes until tender. It is a comforting family meal found across the Middle East and Mediterranean.`],
      ['h2', `8. Middle Eastern lamb flatbread`],
      ['p', `Lahm bi ajeen is a thin flatbread topped with spiced lamb. Mix raw lamb mince with finely chopped onion, tomato, capsicum, parsley, pomegranate molasses, allspice and chilli. Spread thinly over rolled-out pizza dough or store-bought flatbreads and bake at 250°C for 8 to 10 minutes. Serve with lemon wedges, yoghurt and a fresh salad.`],
      ['h2', `Lamb mince meal ideas for busy weeks`],
      ['ul', [
        `Cook a big batch of plain browned lamb mince with onion and garlic, then season portions differently through the week.`,
        `Make double koftas or burgers and freeze half uncooked.`,
        `Turn leftover keema into stuffed parathas or toasted wraps.`,
        `Use spiced lamb mince as a topping for hummus with toasted pine nuts.`,
        `Stir leftover shepherd's pie filling through pasta for a quick ragu.`,
      ]],
      ['h2', `Cooking for a crowd: wholesale lamb`],
      ['p', `If you cater for large groups, restaurants or community events, buying wholesale lamb is far more economical than small packs. We supply lamb mince, diced lamb and curry pieces in bulk; see our [lamb curry pieces carton](/product/lamb-curry-pieces-carton/) and our [halal meat wholesale](/halal-meat-wholesale/) page for trade enquiries.`],
      ['h3', `Whole lamb price vs buying cuts`],
      ['p', `Families who eat a lot of lamb sometimes ask about the whole lamb price compared with buying individual cuts. A whole or half lamb usually works out cheaper per kilo, and you get a variety of cuts, from chops and legs to shanks and mince. The trade-off is that you need freezer space and a plan for every cut. Our [whole lamb carcass](/product/whole-lamb-carcass/) and [half lamb carcass](/product/half-lamb-carcass/) pages show current prices, and our [quarter lamb](/blog/quarter-lamb-buying-guide/) guide explains what you get.`],
      ['h2', `Lamb mince questions`],
      ['h3', `Is lamb mince fattier than beef mince?`],
      ['p', `It is often a little fattier, which gives it great flavour. Drain off excess fat after browning if you prefer a lighter dish.`],
      ['h3', `How long does lamb mince keep?`],
      ['p', `Fresh mince should be cooked within one to two days of purchase, or frozen. Cook it through to 71 to 75°C in the centre.`],
      ['h3', `Can I substitute lamb mince for beef mince?`],
      ['p', `Yes, in almost any recipe. Lamb mince gives a richer, more aromatic result, especially in spiced dishes.`],
      ['h2', `Buy halal lamb mince online`],
      ['p', `Lamb mince, lamb kofta and diced lamb are all in our [halal lamb range](/shop/lamb/), certified halal by Halal Control Australia and delivered chilled from Greenacre, Sydney, to anywhere in Australia.`],
    ],
  },
  {
    ...meta('lamb-skewers'),
    title: 'Lamb Skewers: Marinades, Cuts and Perfect Grilling',
    seoTitle: 'Lamb Skewers: Easy Marinades and Grilling Tips',
    excerpt: `A recipe for lamb skewers that stay juicy: the best halal cuts, four marinades, threading lamb on a skewer, grilling times and what to serve alongside.`,
    body: [
      ['p', `Few things smell better than lamb skewers sizzling over hot coals. Lamb's rich flavour and natural fat make it perfect for grilling, and it takes on marinades from every corner of the world: Middle Eastern spice, Greek lemon and oregano, Indian yoghurt and garam masala, or Chinese cumin and chilli. This guide gives you a dependable recipe for lamb skewers, four marinades, tips for threading lamb on a skewer and grilling times for every preference.`],
      ['h2', `Best cuts for lamb skewers`],
      ['p', `Skewers cook quickly over high heat, so use a tender cut with some fat:`],
      ['ul', [
        `[Lamb leg](/product/lamb-leg-butterflied/): the classic choice, balanced and easy to cube.`,
        `[Lamb shoulder](/product/lamb-shoulder-boned-and-rolled/): juicier and more forgiving thanks to extra fat.`,
        `[Lamb rump](/product/lamb-rump/): tender and full of flavour.`,
        `[Lamb backstrap](/product/lamb-backstrap/): the most tender, best cooked medium-rare.`,
        `[Lamb cocktail kebabs](/product/lamb-cocktail-kebabs/): ready-made and perfect for parties.`,
      ]],
      ['p', `Trim off any thick sinew and cut the lamb into 2.5 to 3 cm cubes. Even sizes are the key to even cooking.`],
      ['h2', `Recipe for lamb skewers: the basic method`],
      ['p', `Serves four.`],
      ['ul', [
        `800 g boneless lamb leg or shoulder, cubed`,
        `One marinade from the list below`,
        `1 red onion and 1 red capsicum, cut into chunks (optional)`,
        `Bamboo skewers soaked for 30 minutes, or metal skewers`,
      ]],
      ['p', `Toss the lamb with your chosen marinade and refrigerate for 2 to 12 hours. Thread the lamb onto skewers, alternating with onion and capsicum if you like. Heat the grill or barbecue to high and oil the bars. Grill for 8 to 10 minutes, turning every 2 minutes. Rest for 3 minutes before serving.`],
      ['h2', `Four marinades`],
      ['h3', `1. Middle Eastern shish`],
      ['p', `Olive oil, grated onion juice, garlic, lemon, cumin, coriander, paprika, allspice, cinnamon and salt. Serve with garlic sauce, flatbread and pickles. This is the classic lamb shish kebab flavour found in Lebanese and Turkish grills.`],
      ['h3', `2. Greek`],
      ['p', `Olive oil, lemon zest and juice, garlic, dried oregano, pepper and salt. Serve with tzatziki and Greek salad, or see our [lamb souvlaki](/blog/lamb-souvlaki/) recipe.`],
      ['h3', `3. Indian tikka`],
      ['p', `Thick yoghurt, ginger-garlic paste, Kashmiri chilli, garam masala, cumin, turmeric, lemon juice and salt. Yoghurt is a gentle tenderiser, so you can marinate overnight. Serve with mint chutney and naan.`],
      ['h3', `4. Xinjiang cumin lamb`],
      ['p', `Chinese street-food lamb skewers from Xinjiang are simply seasoned with oil and salt, grilled, then showered with a mix of ground cumin, chilli flakes and toasted sesame seeds in the final minute. Use shoulder with plenty of fat for authentic flavour.`],
      ['h2', `Threading lamb on a skewer`],
      ['p', `How you thread lamb on a skewer affects how it cooks. Leave a tiny gap between pieces so heat circulates; packing them tightly leaves the centres underdone. Thread through the centre of each cube so it sits flat. Flat metal skewers stop the meat spinning when turned, and two parallel skewers make larger kebabs much easier to handle. Keep vegetables on separate skewers if you want precise cooking, as they cook at a different rate.`],
      ['h2', `Grilling times`],
      ['table', { caption: 'Lamb skewer grilling times (3 cm cubes, high heat)', head: ['Doneness', 'Total time', 'Internal temperature'], rows: [['Medium-rare', '7 to 8 minutes', '57 to 60°C'], ['Medium', '9 to 10 minutes', '62 to 65°C'], ['Well done', '11 to 12 minutes', '70°C and above']] }],
      ['p', `Lamb shoulder can be cooked a little longer without drying out; leg and backstrap are best at medium-rare to medium.`],
      ['h2', `What to serve with lamb skewers`],
      ['ul', [
        `Warm flatbread, hummus and garlic sauce`,
        `Tabbouleh or fattoush salad`,
        `Saffron or herbed rice, or couscous with herbs and lemon`,
        `Grilled vegetables and halloumi`,
        `Yoghurt with mint and cucumber`,
      ]],
      ['h2', `Feeding a crowd: lamb wholesale`],
      ['p', `Skewers are a favourite for weddings, Eid gatherings and community barbecues. If you are catering for a big group, buying lamb wholesale is far more economical. We supply leg, shoulder and diced lamb in bulk, plus catering packs; see our [whole lamb catering pack](/product/whole-lamb-catering-pack/) and [halal meat wholesale](/halal-meat-wholesale/) page for trade options.`],
      ['h2', `Lamb cutlets price per kg vs skewers`],
      ['p', `Customers sometimes compare the lamb cutlets price per kg with leg or shoulder when planning a barbecue. Cutlets are a premium cut and cost more per kilo, partly because of the bone and trimming. For skewers, leg and shoulder give excellent results at a lower price, while cutlets are best grilled whole as a treat. You can compare prices on our [frenched lamb cutlets](/product/frenched-lamb-cutlets-price/) and [butterflied leg](/product/lamb-leg-butterflied/) pages.`],
      ['h2', `Lamb skewers questions`],
      ['h3', `Why are my lamb skewers tough?`],
      ['p', `They were overcooked, the cubes were too small, or a slow-cooking cut was used. Choose leg, shoulder or rump, cut 3 cm cubes and grill hot and fast.`],
      ['h3', `Can I cook lamb skewers in the oven?`],
      ['p', `Yes. Place them on a rack over a tray and cook under a very hot grill for 8 to 10 minutes, turning regularly, or bake at 230°C for 12 to 15 minutes.`],
      ['h3', `Can I freeze marinated skewers?`],
      ['p', `Yes, for up to two months. Freeze them flat on a tray, then bag. Thaw overnight in the fridge before grilling.`],
      ['h2', `Cooking over charcoal`],
      ['p', `Charcoal gives lamb skewers their classic smoky flavour. Light a chimney of lump charcoal and wait until the coals are covered in fine white ash, about 20 to 30 minutes. Spread them in an even layer under the grill, with a cooler zone at one side. The grill is hot enough when you can hold your hand 10 cm above the bars for only two or three seconds. Grill the skewers over the hottest part, moving them to the cooler side if fat drips and causes flare-ups.`],
      ['p', `In the Middle East and Central Asia, skewers are often grilled on a mangal, a long, narrow charcoal box with no grill bars; the skewers rest across the edges and are turned constantly. If you have one, use flat metal skewers and keep them moving for even cooking.`],
      ['h2', `Planning quantities for a party`],
      ['p', `Allow about 200 g of boneless lamb per adult if skewers are the main dish, or 120 to 150 g if there are plenty of other dishes. One kilo of cubed lamb makes about 12 to 15 medium skewers. Marinate the meat the day before, thread the skewers in the morning, and keep them covered in the fridge on trays until you are ready to grill. Cook in batches and keep the cooked skewers warm, loosely covered, while the rest finish.`],
      ['h2', `Buy halal lamb for skewers`],
      ['p', `Lamb leg, shoulder, rump, backstrap and cocktail kebabs are all in our [halal lamb range](/shop/lamb/), certified halal by Halal Control Australia and delivered chilled from Greenacre, Sydney, to anywhere in Australia.`],
    ],
  },
  {
    ...meta('lamb-chops-in-air-fryer'),
    title: 'Lamb Chops in Air Fryer: Times, Temperatures and Tips',
    seoTitle: 'Lamb Chops in Air Fryer: Quick, Easy Guide',
    excerpt: `How to cook lamb chops in air fryer: times for loin chops, cutlets and forequarter chops, the right temperature, seasoning ideas and tips for a golden crust.`,
    body: [
      ['p', `Cooking lamb chops in air fryer baskets has become one of the most popular ways to get a quick, juicy weeknight dinner. The circulating hot air browns the outside of the chops and renders the fat, while the inside stays tender, with less mess than pan-frying and no smoky kitchen. This guide explains how to cook air fryer lamb chops for every cut, with timings, temperatures, seasoning ideas and tips for the best results.`],
      ['h2', `Which lamb chops work best?`],
      ['p', `Most lamb chops cook beautifully in an air fryer, but each cut behaves a little differently:`],
      ['ul', [
        `[Lamb loin chops](/product/lamb-loin-chops/): T-shaped chops with a piece of loin and fillet. Tender, meaty and ideal for the air fryer.`,
        `[Frenched lamb cutlets](/product/frenched-lamb-cutlets-price/): small, elegant and tender; they cook very quickly.`,
        `[Lamb forequarter chops](/product/lamb-forequarter-chops/): from the shoulder, with more fat and connective tissue. Very flavourful and economical; cook them a little longer.`,
        `[Lamb leg steaks](/product/lamb-leg-steaks/): lean, boneless and quick.`,
      ]],
      ['h2', `Lamb chops air fryer times`],
      ['p', `Preheat the air fryer to 200°C for 3 to 5 minutes. Cook the chops in a single layer, turning halfway. Times below are for chops about 2.5 cm thick.`],
      ['table', { caption: 'Air fryer lamb chops at 200°C (turn halfway)', head: ['Cut', 'Medium-rare', 'Medium', 'Well done'], rows: [['Loin chops', '8 to 9 minutes', '10 to 11 minutes', '12 to 14 minutes'], ['Frenched cutlets', '6 to 7 minutes', '8 minutes', '9 to 10 minutes'], ['Forequarter chops', 'Not recommended', '12 to 14 minutes', '15 to 16 minutes'], ['Leg steaks', '7 to 8 minutes', '9 to 10 minutes', '11 to 12 minutes']] }],
      ['p', `Air fryers vary, so treat these as a starting point and check with a thermometer: 57 to 60°C for medium-rare, 62 to 65°C for medium, 70°C for well done. Rest the chops for 3 to 5 minutes before serving.`],
      ['h2', `How to cook air fryer lamb chops`],
      ['ul', [
        `Take the chops out of the fridge 20 to 30 minutes before cooking.`,
        `Pat them completely dry with paper towel; dry surfaces brown better.`,
        `Brush lightly with oil and season generously with salt and pepper.`,
        `Add your chosen herbs or spices (see below).`,
        `Preheat the air fryer and arrange the chops in a single layer with space between them.`,
        `Cook, turning halfway, until they reach your preferred doneness.`,
        `Rest for a few minutes, then serve.`,
      ]],
      ['h3', `Getting a golden crust`],
      ['p', `Air fryers brown well, but a few tricks help. Do not overcrowd the basket; cook in batches if needed. Score the fat on the edge of loin chops every 2 cm so it renders and crisps. For an extra crust, sear the chops in a hot pan for 1 minute a side before air frying, or finish them for a minute at the highest setting.`],
      ['h2', `Seasoning ideas`],
      ['ul', [
        `Garlic and rosemary: olive oil, crushed garlic, chopped rosemary, salt and pepper.`,
        `Greek: lemon zest, oregano, garlic and olive oil.`,
        `Middle Eastern: cumin, coriander, paprika, sumac and a little cinnamon.`,
        `Indian: yoghurt, garam masala, chilli and ginger-garlic paste.`,
        `Moroccan: ras el hanout, honey and lemon.`,
      ]],
      ['p', `For stronger flavour, marinate the chops for a few hours. Our [marinated lamb chops](/blog/marinated-lamb-chops/) guide has more marinades.`],
      ['h2', `What to serve with lamb chops`],
      ['p', `Air fryer lamb chops pair well with air fryer potatoes or chips (cook them first and keep warm), a Greek salad, minted peas, roasted vegetables, couscous or a simple green salad. A spoon of mint sauce, tzatziki or salsa verde finishes the plate.`],
      ['h2', `Air fryer lamb chops vs pan and grill`],
      ['p', `A very hot cast iron pan or barbecue gives the deepest crust, but an air fryer is more convenient, cleaner and more consistent, especially for beginners. It is also excellent for cooking a side dish at the same time in a dual-basket model. For thick chops and cutlets cooked medium-rare, some cooks prefer the pan; for well-done or forequarter chops, the air fryer is very forgiving.`],
      ['h2', `Lamb prices Australia: getting value from chops`],
      ['p', `Lamb prices Australia-wide move with the seasons, and chops vary a lot in cost by cut. Forequarter chops are the most economical and full of flavour, loin chops sit in the middle, and frenched cutlets are the premium option. Buying a half or whole lamb is another way to get chops at a lower price per kilo, along with all the other cuts. If you are interested, our [whole lamb meat for sale](/product/whole-lamb-carcass/) is cut to your requirements; see our [whole lamb](/whole-lamb-aqeeqah-qurbani/) page for details.`],
      ['h2', `Lamb chops in air fryer questions`],
      ['h3', `Do I need to flip lamb chops in the air fryer?`],
      ['p', `Yes, turning them halfway gives even browning on both sides.`],
      ['h3', `Can I cook frozen lamb chops in the air fryer?`],
      ['p', `It is possible: cook at 180°C for about 15 to 18 minutes, turning halfway, until cooked through. Thawed chops give a better texture and more even cooking, so thaw them overnight in the fridge when you can.`],
      ['h3', `Should I use oil?`],
      ['p', `A light brush or spray of oil helps the seasoning stick and improves browning. Lamb has its own fat, so you need very little.`],
      ['h3', `How do I stop smoke?`],
      ['p', `Trim excess fat, put a little water in the drawer under the basket if your manual allows, and clean the air fryer regularly.`],
      ['h2', `A complete air fryer dinner`],
      ['p', `You can cook a full dinner in the air fryer with a little planning. Start with potato wedges or baby potatoes, tossed in oil, salt and rosemary, at 200°C for 18 to 20 minutes, shaking halfway. Move them to a warm oven or a covered bowl, then cook the lamb chops. While the chops rest, give some broccoli florets or green beans, tossed in oil and garlic, 5 to 6 minutes in the air fryer. In a dual-basket model, you can cook the chops and potatoes at the same time using the sync function.`],
      ['p', `For a quick sauce, mix Greek yoghurt with chopped mint, a squeeze of lemon and a pinch of salt, or warm a few tablespoons of mint jelly with a splash of water. A simple tomato, cucumber and red onion salad dressed with olive oil and lemon completes the plate.`],
      ['h2', `Cleaning up`],
      ['p', `Lamb fat collects in the air fryer drawer. Let it cool, pour off the fat into a container for disposal, then wash the basket and drawer in warm soapy water. Lining the drawer with a perforated baking paper liner makes clean-up easier, but never cover the whole basket, as it blocks the airflow.`],
      ['h2', `Buy halal lamb chops online`],
      ['p', `Loin chops, cutlets, forequarter chops and leg steaks are all in our [halal lamb range](/shop/lamb/), certified halal by Halal Control Australia and delivered chilled from Greenacre, Sydney, to anywhere in Australia.`],
    ],
  },
  {
    ...meta('marinated-lamb-chops'),
    title: 'Marinated Lamb Chops: Five Marinades and How to Cook Them',
    seoTitle: 'Marinated Lamb Chops: 5 Easy Marinades',
    excerpt: `Marinated lamb chops five ways, how long to marinate, a lamb loin chops recipe for the grill, and how cooking lamb chops in slow cooker gives tender results.`,
    body: [
      ['p', `A good marinade turns ordinary lamb chops into something special. Lamb's rich, slightly sweet flavour pairs with bold ingredients such as garlic, rosemary, lemon, yoghurt, spices and honey, and a few hours in a marinade seasons the meat deeply and helps it brown beautifully. This guide gives you five tried-and-tested marinades for marinated lamb chops, explains how long to marinate, and covers grilling, pan-frying and slow cooking.`],
      ['h2', `Choosing your chops`],
      ['ul', [
        `[Lamb loin chops](/product/lamb-loin-chops/): tender and meaty, best grilled or pan-fried.`,
        `[Lamb forequarter chops](/product/lamb-forequarter-chops/): fattier and full of flavour; great for marinating, grilling to medium or slow cooking.`,
        `[Frenched lamb cutlets](/product/frenched-lamb-cutlets-price/): small and elegant; marinate briefly and cook quickly.`,
        `[Lamb leg steaks](/product/lamb-leg-steaks/): lean, boneless and quick.`,
      ]],
      ['h2', `How long to marinate lamb chops`],
      ['p', `Most marinades need 2 to 12 hours. Oil-and-herb marinades can go overnight. Yoghurt-based marinades are gentle and can also go overnight. Very acidic marinades, with lots of lemon juice or vinegar, should be kept to 4 hours or less, as the acid can make the surface of the meat mushy. Always marinate in the fridge, in a covered dish or zip-lock bag, and turn the chops once or twice.`],
      ['h2', `Five marinades`],
      ['h3', `1. Garlic, rosemary and lemon`],
      ['p', `Mix 1/4 cup olive oil, 4 crushed garlic cloves, 2 tablespoons chopped rosemary, the zest of a lemon and 1 tablespoon juice, salt and pepper. The classic Australian flavour for a barbecue.`],
      ['h3', `2. Middle Eastern spice`],
      ['p', `Mix olive oil, garlic, lemon juice, 1 teaspoon each of cumin, coriander and paprika, 1/2 teaspoon each of cinnamon and allspice, and a pinch of chilli. Serve with garlic sauce and tabbouleh.`],
      ['h3', `3. Yoghurt and mint`],
      ['p', `Mix 1/2 cup thick yoghurt, 2 crushed garlic cloves, a handful of chopped mint, the juice of half a lemon, 1 teaspoon cumin and salt. Yoghurt tenderises gently and gives a lovely charred crust.`],
      ['h3', `4. Honey, soy and ginger`],
      ['p', `Mix 2 tablespoons soy sauce, 1 tablespoon honey, 1 tablespoon grated ginger, 2 garlic cloves and 1 teaspoon sesame oil. The sugars caramelise quickly, so cook over medium-high rather than very high heat.`],
      ['h3', `5. Harissa and lemon`],
      ['p', `Mix 2 tablespoons harissa paste, 2 tablespoons olive oil, the juice of a lemon, a crushed garlic clove and a pinch of salt. Smoky, spicy and great with couscous.`],
      ['h2', `Lamb loin chops recipe: grilled`],
      ['p', `This lamb loin chops recipe works with any of the marinades above. Remove 8 marinated loin chops from the fridge 20 minutes before cooking and wipe off any excess marinade. Heat a barbecue or chargrill to high and oil the bars. Stand the chops on their fat edge for 1 to 2 minutes to render and crisp the fat, then lay them flat and grill for 3 to 4 minutes a side for medium-rare to medium. Rest for 5 minutes, then serve with lemon wedges and a fresh salad.`],
      ['h3', `In a pan`],
      ['p', `Heat a heavy frying pan over medium-high heat with a little oil. Cook the chops for 3 to 4 minutes a side, rendering the fat edge first. Marinades with honey or sugar can burn, so lower the heat slightly and keep an eye on them. You can also cook them in an air fryer; see our [lamb chops in air fryer](/blog/lamb-chops-in-air-fryer/) guide.`],
      ['h2', `Cooking lamb chops in slow cooker`],
      ['p', `Cooking lamb chops in slow cooker pots is ideal for forequarter chops, which have plenty of connective tissue and become meltingly tender after a few hours. Brown 1.5 kg of marinated forequarter chops in a hot pan, then place them in the slow cooker on a bed of sliced onions, carrots and potatoes. Add 1 cup stock, a tablespoon of tomato paste and a few sprigs of rosemary. Cook on low for 6 to 7 hours or high for 3 to 4. Thicken the juices with a little cornflour if you like. Our [slow cooked lamb chops](/blog/slow-cooked-lamb-chops/) and [lamb chop casserole](/blog/lamb-chop-casserole/) guides have full recipes.`],
      ['h2', `Serving ideas`],
      ['ul', [
        `Greek salad and lemon potatoes`,
        `Herbed couscous and roast vegetables`,
        `Minted peas and creamy mash`,
        `Flatbread, hummus and pickles`,
        `A simple rocket and parmesan salad`,
      ]],
      ['h2', `A whole lamb for a big celebration`],
      ['p', `For weddings, Eid and family celebrations, many families roast a whole lamb on a spit. A rotisserie for whole lamb needs a sturdy motor and spit rod, plenty of charcoal and about 4 to 6 hours of cooking for a typical lamb. If you have whole lamb for sale on your shopping list for an occasion like this, our [whole lamb carcass](/product/whole-lamb-carcass/) is delivered chilled and can be prepared for the spit. Our [lamb spit](/blog/lamb-spit-roast-guide/) guide explains the process step by step.`],
      ['h2', `Marinated lamb chops questions`],
      ['h3', `Should I salt the marinade?`],
      ['p', `Yes. Salt helps season the meat throughout. Use about 1 teaspoon of salt per kilo of chops.`],
      ['h3', `Can I freeze marinated lamb chops?`],
      ['p', `Yes. Place the chops and marinade in a freezer bag, flatten and freeze for up to two months. They marinate as they thaw overnight in the fridge.`],
      ['h3', `Can I reuse the marinade?`],
      ['p', `Do not use raw marinade as a sauce unless you boil it first for several minutes. It is safer to set aside a little fresh marinade before adding the meat.`],
      ['h2', `Getting the best char without burning`],
      ['p', `Marinades containing honey, sugar or yoghurt brown quickly, which is great for flavour but can scorch over very high heat. Wipe off excess marinade before cooking, cook over medium-high heat rather than the hottest setting, and turn the chops more often. If the outside is browning faster than the inside is cooking, move them to a cooler part of the grill or finish them in a 180°C oven for a few minutes. Brush on a little reserved, unused marinade in the final minute for a glossy finish.`],
      ['h2', `Marinade safety tips`],
      ['p', `Always marinate meat in the fridge, never on the bench. Use a glass, ceramic or food-safe plastic container, as acidic marinades can react with aluminium. Keep raw meat and its marinade away from cooked food, and wash your hands, boards and tongs after handling it. If you want extra sauce for serving, set aside a portion of fresh marinade before it touches the raw lamb.`],
      ['h2', `Buy halal lamb chops online`],
      ['p', `Loin chops, forequarter chops, cutlets and leg steaks are all in our [halal lamb range](/shop/lamb/), certified halal by Halal Control Australia and delivered chilled from Greenacre, Sydney, to anywhere in Australia.`],
    ],
  },
  {
    ...meta('how-do-you-cook-lamb-cutlets'),
    title: 'How Do You Cook Lamb Cutlets? Pan, Grill and Oven Methods',
    seoTitle: 'How Do You Cook Lamb Cutlets? Easy Guide',
    excerpt: `How do you cook lamb cutlets perfectly? Pan, grill, crumbed and oven methods, cooking times for pink cutlets, a lamb cutlets recipe and serving ideas.`,
    body: [
      ['p', `Lamb cutlets are one of the most elegant cuts you can serve: small, tender chops cut from the rack, with a clean, frenched bone that makes a natural handle. They cook in minutes, look beautiful on the plate and are loved by adults and children alike. But because they are small and lean, they overcook easily. So how do you cook lamb cutlets so they stay pink, juicy and golden? This guide covers pan-frying, grilling, crumbing and oven methods, with times, temperatures and a favourite lamb cutlets recipe.`],
      ['h2', `What are lamb cutlets?`],
      ['p', `Lamb cutlets are cut from the rack of lamb, between the ribs. Each one has a small eye of tender loin meat and a rib bone. "Frenched" cutlets have the meat and fat scraped away from the end of the bone for a neat appearance. They are one of the most tender cuts on the lamb, similar to a lamb version of a scotch fillet or rib-eye steak. Our [frenched lamb cutlets](/product/frenched-lamb-cutlets-price/) are ready to cook, and a whole [frenched lamb rack](/product/lamb-rack-frenched/) can be cut into cutlets or roasted whole.`],
      ['h2', `How to cook lamb cutlets in a pan`],
      ['p', `Pan-frying is the most popular method and gives a beautiful golden crust:`],
      ['ul', [
        `Take the cutlets out of the fridge 20 minutes before cooking and pat them dry.`,
        `Brush with a little oil and season with salt and pepper.`,
        `Heat a heavy frying pan over medium-high heat.`,
        `Stand the cutlets on their fat edge (use tongs) for 1 to 2 minutes to render and crisp the fat.`,
        `Lay them flat and cook for 2 to 3 minutes a side for medium-rare.`,
        `Add a knob of butter, garlic and rosemary for the final minute and baste.`,
        `Rest for 3 minutes before serving.`,
      ]],
      ['h2', `Cooking times for lamb cutlets`],
      ['table', { caption: 'Lamb cutlet cooking times (2 cm thick, medium-high heat)', head: ['Doneness', 'Time per side', 'Internal temperature'], rows: [['Rare', '1.5 to 2 minutes', '52 to 55°C'], ['Medium-rare', '2 to 3 minutes', '57 to 60°C'], ['Medium', '3 to 4 minutes', '62 to 65°C'], ['Well done', '4 to 5 minutes', '70°C and above']] }],
      ['p', `Lamb cutlets are at their best medium-rare to medium. Thicker, double-bone cutlets need a minute or two longer.`],
      ['h2', `On the barbecue`],
      ['p', `Heat the grill to high and oil the bars. Grill cutlets for 2 to 3 minutes a side for medium-rare, rotating them 90 degrees after a minute for crosshatch marks. Wrap the exposed bones in a little foil if you want them to stay clean and pale. Cutlets cook very quickly on a hot barbecue, so stay close.`],
      ['h2', `Lamb cutlets recipe: crumbed cutlets`],
      ['p', `Crumbed lamb cutlets are an Australian family classic. Flatten 12 cutlets slightly with a meat mallet. Dust them in seasoned flour, dip in beaten egg, then press into breadcrumbs mixed with grated parmesan, chopped parsley and lemon zest. Chill for 15 minutes. Shallow-fry in hot oil for 2 to 3 minutes a side until golden, or air fry at 200°C for 8 to 10 minutes, turning halfway. Serve with lemon wedges, mashed potato and peas. Children love them, because the bone makes a perfect handle.`],
      ['h2', `In the oven`],
      ['p', `For a crowd, sear cutlets in a hot pan for 1 minute a side, then transfer them to a tray and roast at 200°C for 4 to 6 minutes. Or roast a whole frenched rack and slice it into cutlets at the table; see our [rack of lamb cooking time](/blog/rack-of-lamb-cooking-time/) guide.`],
      ['h2', `Marinades and flavours`],
      ['ul', [
        `Garlic, rosemary and olive oil: the classic.`,
        `Dijon mustard and herb crust: brush with mustard and press in chopped herbs and breadcrumbs.`,
        `Middle Eastern: cumin, sumac, garlic and lemon.`,
        `Mint and yoghurt: fresh and tangy.`,
        `Moroccan: ras el hanout and honey.`,
      ]],
      ['p', `Cutlets are small, so 30 minutes to 4 hours of marinating is enough. See our [marinated lamb chops](/blog/marinated-lamb-chops/) guide for more ideas.`],
      ['h2', `What to serve with lamb cutlets`],
      ['p', `Serve cutlets with creamy mashed potato, minted peas, roasted root vegetables, Greek salad, herbed couscous, or a fresh green salad. A spoonful of mint sauce, salsa verde or chimichurri adds brightness.`],
      ['h2', `Whole lamb, spit roasts and celebrations`],
      ['p', `Cutlets are a premium cut, and many families who love them buy a half or whole lamb to get them at better value along with every other cut. For big celebrations, a lamb for spit roasting is another popular choice: it feeds a crowd and makes a memorable centrepiece. If you are looking for a full lamb for sale, our [whole lamb carcass](/product/whole-lamb-carcass/) can be cut into cutlets, chops, legs and shanks, or left whole for the spit. See our [whole lamb](/whole-lamb-aqeeqah-qurbani/) page and [lamb spit](/blog/lamb-spit-roast-guide/) guide.`],
      ['h2', `Lamb cutlets questions`],
      ['h3', `How many lamb cutlets per person?`],
      ['p', `Allow three to four cutlets per adult as a main course, or two as part of a larger meal.`],
      ['h3', `Are lamb cutlets and lamb chops the same?`],
      ['p', `Cutlets are a type of chop, cut from the rack. Loin chops come from the loin, and forequarter chops from the shoulder. All are chops, but cutlets are the most tender and elegant.`],
      ['h3', `Why are my lamb cutlets tough?`],
      ['p', `They were almost certainly overcooked. Cutlets are small and lean, so even a minute too long can dry them out. Use a hot pan, cook briefly and rest them.`],
      ['h3', `Can I cook lamb cutlets from frozen?`],
      ['p', `It is better to thaw them overnight in the fridge. They are so thin that they thaw quickly and cook far more evenly.`],
      ['h2', `Lamb cutlets for entertaining`],
      ['p', `Lamb cutlets make perfect finger food for parties because the bone acts as a handle. Marinate them in olive oil, garlic, lemon zest and herbs, and grill or pan-fry them just before guests arrive. Serve them on a platter with a bowl of salsa verde, chimichurri or tzatziki for dipping. Allow two cutlets per person when serving them as canapés. For a sit-down dinner, arrange three or four cutlets per plate over creamy mash or a bed of herbed couscous, with roasted cherry tomatoes and a drizzle of the pan juices.`],
      ['h2', `A simple pan sauce`],
      ['p', `After cooking the cutlets, pour off most of the fat from the pan, add a crushed garlic clove and a teaspoon of chopped rosemary, then a splash of stock and a squeeze of lemon. Scrape up the browned bits, simmer for a minute, stir in a knob of butter and spoon it over the cutlets. It takes two minutes and makes the dish feel restaurant-worthy.`],
      ['h2', `Buy halal lamb cutlets online`],
      ['p', `Frenched lamb cutlets and frenched racks are in our [halal lamb range](/shop/lamb/), certified halal by Halal Control Australia and delivered chilled from Greenacre, Sydney, to anywhere in Australia.`],
    ],
  },
  {
    ...meta('lamb-cooking-temperature'),
    title: 'Lamb Cooking Temperature: Doneness Chart for Every Cut',
    seoTitle: 'Lamb Cooking Temperature: Complete Guide',
    excerpt: `The right lamb cooking temperature for every cut and doneness: internal temperatures, roast lamb meat temperature, oven settings and resting times.`,
    body: [
      ['p', `Lamb is one of the most rewarding meats to cook, but the difference between a juicy, pink roast and a dry, grey one is just a few degrees. Knowing the right lamb cooking temperature, both for your oven and for the inside of the meat, takes the guesswork out of every roast, chop and cutlet. This guide explains internal temperatures for every doneness, oven settings for different cuts, how resting affects the final result and how to use a thermometer.`],
      ['h2', `Two temperatures that matter`],
      ['p', `When cooking lamb, there are two temperatures to think about. The cooking temperature is the heat of your oven, pan or barbecue. The internal temperature is how hot the centre of the meat gets, and it is what determines doneness. A meat thermometer measures the internal temperature and is the most reliable way to know when lamb is ready.`],
      ['h2', `Lamb is done at what temperature?`],
      ['p', `Lamb is done at what temperature depends on how you like it cooked. These are the internal temperatures after resting:`],
      ['table', { caption: 'Lamb internal temperatures (after resting)', head: ['Doneness', 'Internal temperature', 'Remove from heat at', 'Appearance'], rows: [['Rare', '50 to 52°C', '46 to 48°C', 'Deep red centre'], ['Medium-rare', '55 to 58°C', '52 to 54°C', 'Rosy pink'], ['Medium', '60 to 63°C', '56 to 58°C', 'Light pink'], ['Medium-well', '65 to 68°C', '61 to 63°C', 'Faint pink'], ['Well done', '70°C and above', '66°C', 'No pink']] }],
      ['p', `Lamb mince, sausages and kofta should always be cooked to at least 71 to 75°C in the centre, because mincing spreads any surface bacteria through the meat. Whole cuts such as leg, rack and chops can be served pink.`],
      ['h2', `Roast lamb meat temperature: oven settings`],
      ['p', `The best oven temperature depends on the cut. Tender roasting cuts like leg and rack are roasted at a moderate to high heat and served pink. Tougher cuts like shoulder and shank are cooked low and slow until tender and falling apart. For the right roast lamb meat temperature, follow this guide:`],
      ['table', { caption: 'Oven temperatures and approximate times for lamb roasts', head: ['Cut', 'Oven', 'Time', 'Target'], rows: [['Leg on the bone (2 to 2.5 kg)', '180°C', '20 to 25 minutes per 500 g', '57 to 60°C'], ['Butterflied leg', '200°C or barbecue', '30 to 40 minutes', '57 to 60°C'], ['Frenched rack', '200°C after searing', '15 to 20 minutes', '57 to 60°C'], ['Rolled loin', '190°C', '35 to 45 minutes', '57 to 60°C'], ['Shoulder (slow roast)', '150 to 160°C', '4 to 5 hours, covered', 'Falling apart, about 90°C'], ['Shanks (braise)', '160°C', '2.5 to 3 hours', 'Fork tender']] }],
      ['p', `For detailed guides, see our [leg of lamb cooking time](/blog/leg-of-lamb-cooking-time/), [rack of lamb cooking time](/blog/rack-of-lamb-cooking-time/) and [slow roast lamb slow cooker](/blog/slow-roast-lamb-slow-cooker/) posts.`],
      ['h2', `Why resting matters`],
      ['p', `When you take lamb out of the oven, the outside is much hotter than the centre, so heat keeps moving inward and the internal temperature rises by another 3 to 5°C. This is called carryover cooking. That is why you should remove lamb from the oven a few degrees before your target. Resting also lets the juices settle back into the meat. Rest roasts for 15 to 20 minutes, loosely covered with foil, and chops or cutlets for 3 to 5 minutes.`],
      ['h2', `How to use a meat thermometer`],
      ['ul', [
        `Insert the probe into the thickest part of the meat, away from bone and fat.`,
        `For a leg, insert it from the side into the centre of the meatiest part.`,
        `For chops and cutlets, insert it horizontally through the side.`,
        `Check the temperature a little before you expect the meat to be ready.`,
        `Leave-in probe thermometers with an alarm are ideal for roasts.`,
      ]],
      ['h2', `Tips for perfectly cooked lamb`],
      ['ul', [
        `Bring the lamb out of the fridge 30 to 60 minutes before cooking for more even results.`,
        `Season generously, and salt roasts a few hours ahead if you can.`,
        `Sear smaller roasts and racks first for a golden crust.`,
        `Do not slice lamb straight from the oven; rest it first.`,
        `Carve across the grain for tender slices.`,
      ]],
      ['h2', `Buying lamb: lamb for sell and supply`],
      ['p', `Whether you are a home cook or a business looking for lamb for sell to your own customers, consistent sizing and good handling make cooking far more predictable. Evenly sized legs and racks cook evenly and finish at the same time. Our butchers cut every [lamb leg](/product/leg-of-lamb-for-sale-bone-in/), [rack](/product/lamb-rack-frenched/) and [shoulder](/product/lamb-shoulder-boned-and-rolled/) to order, and trade customers can contact our [halal meat wholesale](/halal-meat-wholesale/) team.`],
      ['h2', `Lamb prices in Australia`],
      ['p', `Lamb prices in Australia move with the seasons and market supply, and prices differ significantly between cuts. Leg and shoulder are good-value roasts; racks and backstraps are premium; shanks and forequarter chops are economical slow-cooking cuts. You can see current prices per kilo on every product page in our [halal lamb range](/shop/lamb/).`],
      ['h2', `Lamb cooking temperature questions`],
      ['h3', `Is pink lamb safe to eat?`],
      ['p', `Whole cuts of lamb, such as legs, racks and chops, are generally considered safe when cooked pink, as bacteria are mainly on the surface and are killed during cooking. Minced lamb must be cooked through. Pregnant women, young children, older people and anyone with a weakened immune system may prefer lamb cooked to medium or beyond.`],
      ['h3', `What temperature should slow-cooked lamb reach?`],
      ['p', `Slow-cooked shoulder and shanks are cooked well past well done, to around 90°C or more, so the connective tissue breaks down and the meat falls apart.`],
      ['h3', `Fan-forced or conventional oven?`],
      ['p', `Reduce the temperature by about 20°C for a fan-forced oven.`],
      ['h2', `Temperatures for chops, cutlets and barbecue lamb`],
      ['p', `The same internal temperatures apply to quick-cooking cuts, but they get there much faster. A 2.5 cm loin chop or cutlet cooked over medium-high heat reaches medium-rare in about 6 to 8 minutes in total. Butterflied leg on the barbecue takes 30 to 40 minutes over indirect medium heat, turning occasionally. Because these cuts are thinner, carryover cooking is smaller, about 2 to 3°C, so take them off closer to your target temperature.`],
      ['p', `For lamb mince dishes such as koftas and burgers, always cook to at least 71°C in the centre. A kofta should feel firm and spring back when pressed, with clear juices.`],
      ['h2', `Common lamb cooking mistakes`],
      ['ul', [
        `Cooking straight from the fridge, which leaves the centre cold while the outside overcooks.`,
        `Relying only on cooking times instead of checking the internal temperature.`,
        `Slicing too soon, which lets the juices run onto the board.`,
        `Roasting tough cuts like shoulder quickly; they need low and slow cooking.`,
        `Under-seasoning: lamb needs a generous amount of salt.`,
      ]],
      ['p', `Avoid these and almost every lamb dish you cook will be tender, juicy and full of flavour.`],
      ['h2', `Carving for the juiciest slices`],
      ['p', `Once rested, carve lamb with a long, sharp knife. For a bone-in leg, hold the shank end and cut slices from the thickest part, working down towards the bone, then turn the leg and repeat on the other side. For a boneless roast or butterflied leg, slice across the grain into 1 cm slices. Pour any resting juices over the meat before serving.`],
      ['h2', `Buy halal lamb online`],
      ['p', `Every cut in our [halal lamb range](/shop/lamb/) is certified halal by Halal Control Australia and delivered chilled from Greenacre, Sydney, to anywhere in Australia.`],
    ],
  },
  {
    ...meta('lamb-shank-soup'),
    title: 'Lamb Shank Soup: A Hearty Winter Recipe With Vegetables',
    seoTitle: 'Lamb Shank Soup Recipe: Hearty and Easy',
    excerpt: `A hearty lamb shank soup recipe with barley, lentils and vegetables, stovetop and slow cooker lamb shanks methods, plus tips for a rich, clear broth.`,
    body: [
      ['p', `There are few things more comforting on a cold night than a big bowl of lamb shank soup. Lamb shanks are perfect for soup: the meat is full of flavour, the bones and connective tissue enrich the broth, and after a few hours of simmering the meat falls off the bone. Add barley, lentils and winter vegetables and you have a nourishing, filling meal in a bowl. This lamb shank soup recipe gives you stovetop and slow cooker methods, plus variations from around the world.`],
      ['h2', `Why lamb shanks make great soup`],
      ['p', `Shanks come from the lower leg, a muscle that works hard and is rich in collagen. During long, slow cooking, that collagen breaks down into gelatin, which gives the broth body and a silky mouthfeel. The marrow in the bone adds richness, and the meat becomes so tender it can be pulled apart with a spoon. Shanks are also an economical cut, so a pot of soup feeds a family for very little.`],
      ['h2', `Lamb shank soup recipe`],
      ['p', `Serves six.`],
      ['ul', [
        `4 [lamb shanks](/product/lamb-shanks/) (about 1.6 to 2 kg)`,
        `2 tablespoons olive oil`,
        `1 large onion, 2 carrots, 2 celery sticks and 1 parsnip, diced`,
        `3 cloves garlic, crushed`,
        `2 tablespoons tomato paste`,
        `2.5 litres water or lamb or chicken stock`,
        `1/2 cup pearl barley, rinsed`,
        `1/2 cup red lentils or soup mix, rinsed`,
        `2 bay leaves and a few sprigs of thyme`,
        `1 teaspoon each of ground cumin and smoked paprika (optional)`,
        `Salt, pepper and chopped parsley to finish`,
      ]],
      ['h3', `Method`],
      ['p', `Season the shanks with salt and pepper. Heat the oil in a large, heavy pot and brown the shanks well on all sides; remove. Add the onion, carrot, celery and parsnip and cook for 8 to 10 minutes until softened. Add the garlic, tomato paste and spices and cook for 2 minutes.`],
      ['p', `Return the shanks to the pot and add the water or stock, bay leaves and thyme. Bring to the boil, skim off any foam, then reduce to a gentle simmer. Cover and cook for 1.5 hours. Add the barley and lentils and simmer, partly covered, for another 45 to 60 minutes, until the meat is falling off the bone and the barley is tender.`],
      ['p', `Lift out the shanks, pull the meat off the bones and shred it, discarding the bones and any gristle. Skim the fat from the surface of the soup, return the meat, and season well. Stir through parsley and serve with crusty bread.`],
      ['h2', `Slow cooker lamb shanks soup`],
      ['p', `Slow cooker lamb shanks are ideal for soup, because the gentle heat makes the meat incredibly tender. Brown the shanks and vegetables on the stove first for the best flavour, then transfer everything to the slow cooker with only 2 litres of liquid (slow cookers lose very little to evaporation). Cook on low for 8 hours or high for 5 hours, adding the barley and lentils at the start. Shred the meat and return it to the pot before serving.`],
      ['h2', `Tips for a rich, clear broth`],
      ['ul', [
        `Brown the shanks well: it adds deep flavour and colour.`,
        `Skim the foam as the soup comes to the boil for a clearer broth.`,
        `Keep it at a gentle simmer; vigorous boiling makes the broth cloudy and the meat tough.`,
        `Chill the soup overnight and lift off the set fat for a lighter result.`,
        `Season at the end, as the broth concentrates as it cooks.`,
      ]],
      ['h2', `Variations`],
      ['h3', `Middle Eastern lamb and lentil soup`],
      ['p', `Use cumin, coriander, turmeric and cinnamon, more lentils and no barley. Finish with lemon juice and coriander. It is similar to the harira served during Ramadan.`],
      ['h3', `Scotch broth`],
      ['p', `The classic Scottish soup uses lamb with barley, split peas, carrot, turnip, leek and cabbage. Keep the seasoning simple: salt, pepper and parsley.`],
      ['h3', `Tomato and bean`],
      ['p', `Add a can of crushed tomatoes and a can of cannellini beans in the last 30 minutes, and finish with basil and parmesan.`],
      ['h2', `Lamb halal meat for soups and stews`],
      ['p', `Choosing lamb halal meat that is fresh and well trimmed makes a noticeable difference to soups, because every bit of flavour ends up in the broth. Shanks are our top pick, but [lamb neck](/product/lamb-neck/) and [lamb osso buco](/product/lamb-osso-buco/) also make wonderful soups with plenty of rich, gelatinous broth. For larger households, our [lamb curry pieces carton](/product/lamb-curry-pieces-carton/) is excellent value for soups and stews.`],
      ['h2', `Storing and freezing`],
      ['p', `Lamb shank soup keeps for four days in the fridge, and like most soups it tastes better on the second day. It freezes well for up to three months; barley and lentils thicken the soup on standing, so add a little water or stock when reheating. Reheat until piping hot.`],
      ['h2', `Lamb prices NSW: getting the best value`],
      ['p', `Lamb prices NSW shoppers pay vary with the season, but shanks, necks and forequarter cuts are consistently among the best-value lamb cuts available. Buying a larger pack and freezing portions also helps. You can compare current prices per kilo on every product page in our [halal lamb range](/shop/lamb/).`],
      ['h2', `Lamb shank soup questions`],
      ['h3', `Can I use leftover braised shanks?`],
      ['p', `Yes. Shred leftover [slow cooked lamb shanks](/blog/slow-cooked-lamb-shanks/), add their sauce to stock with vegetables and barley, and simmer for 45 minutes.`],
      ['h3', `How do I make the soup thicker?`],
      ['p', `Add more lentils or barley, or blend a cup of the vegetables and stir them back in.`],
      ['h3', `Can I make it in a pressure cooker?`],
      ['p', `Yes. After browning, pressure-cook the shanks with the vegetables and liquid for 45 minutes, then add the barley and lentils and cook for another 20 minutes at pressure.`],
      ['h2', `Serving suggestions`],
      ['p', `Serve the soup in deep bowls with a drizzle of good olive oil, a squeeze of lemon and plenty of chopped parsley. Warm crusty bread, garlic toast or flatbread is essential for dipping. For a heartier meal, add small pasta such as risoni or broken vermicelli for the last 10 minutes of cooking. A spoonful of yoghurt mixed with garlic and mint is a delicious Middle Eastern-style topping.`],
      ['p', `If you are cooking for children, shred the meat finely and blend a little of the vegetables into the broth for a smooth, mild soup.`],
      ['h2', `Buy halal lamb shanks online`],
      ['p', `Lamb shanks, neck and osso buco are all in our [halal lamb range](/shop/lamb/), certified halal by Halal Control Australia and delivered chilled from Greenacre, Sydney, to anywhere in Australia.`],
    ],
  },
  {
    ...meta('diced-lamb-recipes'),
    title: 'Diced Lamb Recipes: Curries, Tagines, Stews and Skewers',
    seoTitle: 'Diced Lamb Recipes: 7 Easy, Tender Dishes',
    excerpt: `Seven diced lamb recipes: curry, Moroccan tagine, Irish-style stew, biryani, skewers, a Greek kleftiko-style bake and a quick stir-fry.`,
    body: [
      ['p', `Diced lamb is one of the most useful ingredients in the kitchen. Already cut into even pieces, it is ready for curries, tagines, stews, skewers and stir-fries, and its rich flavour suits almost every cuisine. This guide brings together seven of our favourite diced lamb recipes, explains which cut of lamb to use for each, and shares tips for getting tender, flavourful results every time.`],
      ['h2', `Which cut is diced lamb?`],
      ['p', `Diced lamb can come from different parts of the animal, and the cut matters. Diced shoulder is the most popular: it has more fat and connective tissue, so it becomes tender and juicy with slow cooking. Diced leg is leaner and better for quick cooking, such as skewers and stir-fries, or for shorter braises. Our [diced lamb](/product/diced-lamb-boneless/) is boneless and trimmed, and our [lamb curry pieces](/product/lamb-curry-pieces-carton/) include bone for extra flavour in curries and stews.`],
      ['h2', `1. Lamb curry`],
      ['p', `This diced lamb recipe is a reliable home-style curry. Fry 2 sliced onions in oil until deep golden. Add a tablespoon each of ginger and garlic paste, then 2 teaspoons ground coriander, 1 teaspoon each of cumin, chilli and garam masala, and 1/2 teaspoon turmeric. Add 1 kg diced lamb shoulder and brown for 5 minutes, then a can of crushed tomatoes and 1/2 cup yoghurt. Simmer, covered, for 1.5 hours until tender. Finish with coriander and serve with rice or naan.`],
      ['h2', `2. Moroccan lamb tagine`],
      ['p', `Brown 1 kg diced lamb shoulder in batches. Soften an onion with garlic and ginger, add 2 teaspoons ras el hanout, 1 teaspoon each of cumin, cinnamon and paprika, and a pinch of saffron. Return the lamb with 2 cups of stock, a can of chickpeas, a handful of dried apricots or prunes and a strip of preserved lemon. Simmer gently for 1.5 to 2 hours. Finish with toasted almonds and coriander, and serve with couscous.`],
      ['h2', `3. Irish-style lamb stew`],
      ['p', `Layer 1 kg diced lamb shoulder with sliced onions, carrots and potatoes in a heavy pot. Add thyme, bay leaves, salt and pepper and enough stock to almost cover. Simmer, covered, for 2 hours until the lamb is tender and the potatoes have thickened the broth. Simple, comforting and family-friendly.`],
      ['h2', `4. Lamb biryani`],
      ['p', `Marinate diced lamb in yoghurt, ginger, garlic, chilli and biryani masala, then cook it into a thick, spiced curry. Layer it with par-boiled basmati, fried onions, mint, coriander and saffron milk, seal the pot and steam on low heat for 25 minutes. Our [beef biryani](/blog/beef-biryani/) guide explains the layering technique, which works perfectly with lamb.`],
      ['h2', `5. Lamb skewers`],
      ['p', `Diced leg is ideal for grilling. Marinate the cubes in olive oil, lemon, garlic, cumin and oregano, thread onto skewers and grill for 8 to 10 minutes over high heat. See our [lamb skewers](/blog/lamb-skewers/) and [lamb souvlaki](/blog/lamb-souvlaki/) guides for more.`],
      ['h2', `6. Greek kleftiko-style bake`],
      ['p', `Toss diced lamb with olive oil, lemon, garlic, oregano and salt. Place in a baking dish with potato wedges, onion, capsicum and tomato, cover tightly with baking paper and foil, and bake at 160°C for 2.5 hours until meltingly tender. Uncover for the last 20 minutes to brown. Serve with crusty bread and a Greek salad.`],
      ['h2', `7. Quick lamb stir-fry`],
      ['p', `Slice diced leg into thin strips. Stir-fry in a very hot wok with garlic, ginger, cumin and chilli, then add sliced capsicum, onion and spring onion, a splash of soy sauce and a pinch of sugar. Finish with coriander. Ready in 15 minutes and a great introduction to cumin lamb, a favourite in northern Chinese cooking.`],
      ['h2', `Recipes with diced lamb: tips for tenderness`],
      ['ul', [
        `Match the cut to the method: shoulder for slow cooking, leg for quick cooking.`,
        `Brown in batches so the meat sears rather than stews.`,
        `Keep braises at a gentle simmer; boiling toughens the meat.`,
        `Give slow-cooking dishes enough time: 1.5 to 2 hours for shoulder.`,
        `Cook the day before: most stews and curries taste better after a night in the fridge.`,
      ]],
      ['h2', `Lamb meat halal and fresh`],
      ['p', `When you buy diced lamb, look for even, well-trimmed pieces with a fresh red colour and white fat. Lamb meat halal certified from a supplier you trust gives peace of mind as well as flavour. All of our lamb is certified halal by Halal Control Australia and cut fresh in Greenacre, Sydney.`],
      ['h2', `Australia lamb prices and value`],
      ['p', `Australia lamb prices change through the year, but diced shoulder and curry pieces remain among the best-value ways to buy lamb, especially for families and caterers. Larger packs and cartons reduce the price per kilo further. You can compare current prices on our product pages, and trade customers can visit our [halal meat wholesale](/halal-meat-wholesale/) page.`],
      ['h2', `Diced lamb questions`],
      ['h3', `How long does diced lamb take to cook?`],
      ['p', `Diced shoulder needs 1.5 to 2 hours of gentle simmering to become tender. Diced leg cooks in 8 to 10 minutes on skewers or in 3 to 4 minutes in a stir-fry.`],
      ['h3', `Can I freeze diced lamb?`],
      ['p', `Yes, raw diced lamb freezes for up to three months. Cooked curries and stews also freeze well.`],
      ['h3', `Do I need to brown diced lamb?`],
      ['p', `Browning adds flavour and colour, but in a heavily spiced curry you can add the meat to the masala and cook it through without a separate browning step.`],
      ['h2', `Planning a week of diced lamb meals`],
      ['p', `Diced lamb is ideal for batch cooking. On the weekend, cook a big pot of curry or tagine and freeze half in portions for busy weeknights. Use diced leg for quick skewers or a stir-fry midweek, and save the kleftiko-style bake for a relaxed Sunday. A 2 kg pack of diced lamb can easily become three or four different family meals.`],
      ['p', `Freeze cooked dishes in flat, labelled bags so they thaw quickly in the fridge overnight, and always reheat curries and stews until piping hot throughout. Add a squeeze of lemon and fresh herbs after reheating to brighten the flavours.`],
      ['h2', `Buy halal diced lamb online`],
      ['p', `Diced lamb, lamb curry pieces and lamb shoulder are all in our [halal lamb range](/shop/lamb/), delivered chilled from Greenacre, Sydney, to anywhere in Australia.`],
    ],
  },
  {
    ...meta('slow-cooked-lamb-chops'),
    title: 'Slow Cooked Lamb Chops: Tender, Saucy and Easy',
    seoTitle: 'Slow Cooked Lamb Chops: Easy, Tender Recipe',
    excerpt: `Slow cooked lamb chops in a rich onion and tomato gravy: which chops to use, a lamb chops slow cooked recipe, oven and slow cooker timings and serving ideas.`,
    body: [
      ['p', `Slow cooked lamb chops are proof that some of the best meals come from the most economical cuts. Forequarter chops, with their marbling and connective tissue, are often grilled and can be a little chewy. Cook them slowly in a rich gravy, though, and they become so tender the meat slips off the bone. This guide gives you a lamb chops slow cooked recipe for the oven and slow cooker, explains which chops to buy and offers variations and serving ideas.`],
      ['h2', `Which chops are best for slow cooking?`],
      ['p', `Not all chops are suited to slow cooking:`],
      ['ul', [
        `[Lamb forequarter chops](/product/lamb-forequarter-chops/): the best choice. They come from the shoulder, with plenty of fat and connective tissue that melt into the sauce over a long cook.`,
        `[Lamb neck chops](/product/lamb-neck/): another excellent option, rich and gelatinous.`,
        `[Lamb loin chops](/product/lamb-loin-chops/): leaner and more tender; better grilled or pan-fried. They can be slow cooked, but for a shorter time.`,
        `[Frenched cutlets](/product/frenched-lamb-cutlets-price/): too lean and delicate for slow cooking; save them for the pan.`,
      ]],
      ['h2', `Lamb chops slow cooked recipe`],
      ['p', `Serves four to six.`],
      ['ul', [
        `1.5 kg lamb forequarter chops`,
        `2 tablespoons plain flour, seasoned with salt and pepper`,
        `2 tablespoons olive oil`,
        `2 onions, sliced, and 3 cloves garlic, crushed`,
        `2 carrots, cut into chunks, and 2 celery sticks, sliced`,
        `2 tablespoons tomato paste and 400 g can crushed tomatoes`,
        `1 1/2 cups beef or lamb stock`,
        `1 tablespoon brown sugar and 1 tablespoon balsamic or malt vinegar`,
        `2 sprigs rosemary, a few sprigs of thyme and 2 bay leaves`,
        `500 g baby potatoes (optional)`,
      ]],
      ['h3', `Oven method`],
      ['p', `Heat the oven to 160°C. Dust the chops lightly in seasoned flour. Heat the oil in a large, heavy ovenproof casserole and brown the chops well in batches; set aside. Lower the heat, add the onions and cook for 8 minutes until golden, then the garlic, carrots and celery for 3 minutes. Stir in the tomato paste for a minute, then add the tomatoes, stock, sugar, vinegar and herbs. Return the chops, nestling them into the sauce, add the potatoes if using, and bring to a simmer. Cover tightly and bake for 2 to 2.5 hours, until the meat is falling off the bone.`],
      ['h3', `Lamb chops cooked in slow cooker`],
      ['p', `For lamb chops cooked in slow cooker style, brown the chops and cook the onion base on the stove as above, then transfer everything to the slow cooker. Reduce the stock to 1 cup, because slow cookers lose very little liquid. Cook on low for 7 to 8 hours or high for 4 to 5 hours. If the sauce is thin at the end, remove the chops and vegetables, and reduce the sauce in a pan on the stove, or stir in a teaspoon of cornflour mixed with water and cook on high, uncovered, for 15 minutes.`],
      ['h2', `Skimming the fat`],
      ['p', `Forequarter chops release a fair amount of fat during slow cooking. Before serving, tilt the pot and skim the fat from the surface with a ladle or spoon. Even better, cook the dish a day ahead, refrigerate it overnight and lift off the solid fat the next day. The flavour also improves overnight.`],
      ['h2', `Flavour variations`],
      ['ul', [
        `Moroccan: add cumin, cinnamon, ginger and ras el hanout, plus chickpeas and dried apricots.`,
        `Indian: cook the chops in a curry base of onion, ginger, garlic, garam masala, chilli and tomato.`,
        `Honey and mustard: replace the tomatoes with stock, a tablespoon of honey and 2 tablespoons Dijon mustard.`,
        `Greek: add lemon, oregano, potatoes and olives; finish with feta.`,
        `Mushroom gravy: add 250 g sliced mushrooms and a splash of cream at the end.`,
      ]],
      ['h2', `What to serve with slow cooked lamb chops`],
      ['p', `Creamy mashed potato soaks up the gravy beautifully. Steamed green beans, peas, broccoli or roasted vegetables add freshness. For a Mediterranean feel, try couscous or crusty bread, and for an Indian-style version, basmati rice and naan.`],
      ['h2', `Halal lamb meat you can trust`],
      ['p', `Choosing halal lamb meat that is fresh and well cut makes slow cooking easy, because even chops cook evenly. All of our lamb is certified halal by Halal Control Australia and cut in Greenacre, Sydney, with chops cut to a consistent thickness. Read our [lamb chop casserole](/blog/lamb-chop-casserole/) and [marinated lamb chops](/blog/marinated-lamb-chops/) guides for more chop recipes.`],
      ['h2', `Lamb price Australia: why forequarter chops are good value`],
      ['p', `The lamb price Australia-wide varies across cuts and seasons, but forequarter chops are consistently one of the most affordable ways to enjoy lamb. They have more flavour than many premium cuts and, when slow cooked, a texture that rivals much more expensive options. You can compare current prices on our [forequarter chops](/product/lamb-forequarter-chops/) page.`],
      ['h2', `Slow cooked lamb chops questions`],
      ['h3', `Do I need to brown the chops?`],
      ['p', `It is not essential, but browning adds a lot of flavour and colour to the sauce. If you are short on time, skip it and add an extra teaspoon of tomato paste and a pinch of smoked paprika.`],
      ['h3', `Can I use frozen chops?`],
      ['p', `Thaw them in the fridge first. Frozen meat takes too long to come up to a safe temperature in a slow cooker.`],
      ['h3', `How long does it keep?`],
      ['p', `Up to three days in the fridge, or three months in the freezer. Reheat gently until piping hot.`],
      ['h3', `Can I cook them on the stove?`],
      ['p', `Yes. Simmer gently, covered, for about 2 hours, stirring occasionally and adding a splash of stock if needed.`],
      ['h2', `Turning leftovers into new meals`],
      ['p', `Leftover slow cooked lamb chops are easy to transform. Pull the meat from the bones and shred it with the sauce, then use it as a pie filling under puff pastry or mashed potato, toss it through pasta as a rich lamb ragu, or spoon it into toasted wraps with yoghurt and herbs. It also makes an excellent topping for baked potatoes. Store the shredded meat in its sauce in the fridge for up to three days.`],
      ['h2', `Buy halal lamb chops online`],
      ['p', `Forequarter chops, neck and loin chops are all in our [halal lamb range](/shop/lamb/), certified halal by Halal Control Australia and delivered chilled from Greenacre, Sydney, to anywhere in Australia.`],
    ],
  },
]
